trajectory.command:
cat > /etc/nginx/sites-available/gitserver <<'EOF'
server {
    listen 8443 ssl;
    server_name localhost;

    ssl_certificate     /etc/ssl/git-server/cert.pem;
    ssl_certificate_key /etc/ssl/git-server/key.pem;

    root /var/www;
    index index.html;

    location / {
        try_files $uri $uri/ =404;
    }
}
EOF
rm -f /etc/nginx/sites-enabled/default /etc/nginx/sites-enabled/gitserver; ln -s /etc/nginx/sites-available/gitserver /etc/nginx/sites-enabled/gitserver && echo LINK_OK
nginx -t
nginx -s stop 2>/dev/null; sleep 1; nginx && echo NGINX_STARTED
ss -ltnp | grep 8443

